+    <script>
+        let currentExpression = '';
+        let lastResult = null;
+
+        function updateDisplay() {
+            document.getElementById('expression').textContent = currentExpression || '';
+            document.getElementById('error').textContent = '';
+        }
+
+        function showError(message) {
+            document.getElementById('error').textContent = message;
+            document.getElementById('result').textContent = '—';
+            lastResult = null;
+        }
+
+        function showResult(result) {
+            document.getElementById('result').textContent = result;
+            document.getElementById('error').textContent = '';
+            lastResult = result;
+        }
+
+        function appendChar(char) {
+            currentExpression += char;
+            updateDisplay();
+        }
+
+        function clearAll() {
+            currentExpression = '';
+            document.getElementById('expression').textContent = '';
+            document.getElementById('result').textContent = '0';
+            document.getElementById('error').textContent = '';
+            lastResult = null;
+        }
+
+        async function calculate() {
+            if (!currentExpression.trim()) {
+                showError('Enter an expression');
+                return;
+            }
+
+            try {
+                const response = await fetch('/api/calculate', {
+                    method: 'POST',
+                    headers: { 'Content-Type': 'application/json' },
+                    body: JSON.stringify({ expression: currentExpression })
+                });
+
+                const data = await response.json();
+
+                if (!response.ok) {
+                    showError(data.error || 'Calculation failed');
+                    return;
+                }
+
+                showResult(data.result);
+                loadHistory();
+                currentExpression = '';
+                document.getElementById('expression').textContent = data.expression + ' =';
+            } catch (err) {
+                showError('Network error');
+            }
+        }
+
+        async function loadHistory() {
+            try {
+                const response = await fetch('/api/history');
+                const data = await response.json();
+
+                const historyList = document.getElementById('historyList');
+
+                if (data.entries.length === 0) {
+                    historyList.innerHTML = '<div class="empty-history">No calculations yet</div>';
+                    return;
+                }
+
+                historyList.innerHTML = data.entries.map(entry => `
+                    <div class="history-entry">
+                        <div class="history-expression">${escapeHtml(entry.expression)}</div>
+                        <div class="history-result">= ${entry.result}</div>
+                    </div>
+                `).join('');
+            } catch (err) {
+                console.error('Failed to load history:', err);
+            }
+        }
+
+        async function clearHistory() {
+            try {
+                await fetch('/api/history', { method: 'DELETE' });
+                loadHistory();
+            } catch (err) {
+                console.error('Failed to clear history:', err);
+            }
+        }
+
+        function escapeHtml(text) {
+            const div = document.createElement('div');
+            div.textContent = text;
+            return div.innerHTML;
+        }
+
+        // Keyboard support
+        document.addEventListener('keydown', (e) => {
+            if (e.key >= '0' && e.key <= '9') {
+                appendChar(e.key);
+            } else if (['+', '-', '*', '/', '(', ')', '.'].includes(e.key)) {
+                appendChar(e.key);
+            } else if (e.key === 'Enter' || e.key === '=') {
+                e.preventDefault();
+                calculate();
+            } else if (e.key === 'Escape' || e.key === 'c' || e.key === 'C') {
+                clearAll();
+            } else if (e.key === 'Backspace') {
